const $=id=>document.getElementById(id),money=n=>'₹'+Math.round(n).toLocaleString('en-IN'),clamp=(n,a,b)=>Math.min(b,Math.max(a,n));
let goalKind='1000000',saved=null,selected=[],timer=null;
try{const data=JSON.parse(localStorage.getItem('honest-million-v2'));if(data&&Number.isFinite(data.monthly)&&data.monthly>=1000&&data.monthly<=8000&&Number.isFinite(data.growth)&&data.growth>=0&&data.growth<=100&&Array.isArray(data.logs)&&['safe','steady','equity'].every(k=>Number.isFinite(data[k])&&data[k]>=0))saved=data}catch{}
function target(){return goalKind==='usd'?clamp(+$('fx').value||85,1,1000)*1e6:+goalKind}
function goalName(){return goalKind==='usd'?'$1 million ('+money(target())+')':goalKind==='1000000'?'₹10 lakh':'₹1 crore'}
function mix(g){return {safe:(1-g/100)*.2,steady:(1-g/100)*.8,equity:g/100}}
function rate(g){const w=mix(g);return w.safe*.04+w.steady*.06+w.equity*.09}
function project(m,r,step,goal,limit=720){let value=0,points=[0],months=0;while(value<goal&&months<limit){const contribution=m*Math.pow(1+step/100,Math.floor(months/12));value=value*(1+r/12)+contribution;points.push(value);months++}return{months,points,reached:value>=goal}}
function series(m,r,step,n){let v=0,p=[0];for(let i=0;i<n;i++){v=v*(1+r/12)+m*Math.pow(1+step/100,Math.floor(i/12));p.push(v)}return p}
function duration(n){return Math.floor(n/12)+' yrs '+n%12+' mo'}
function update(){const m=+$('monthly').value,g=+$('growth').value,step=+$('stepup').value,w=mix(g),r=rate(g),goal=target(),base=project(m,r,step,goal),low=project(m,r-.03,step,goal),high=project(m,r+.03,step,goal);$('monthlyValue').textContent=money(m);$('leftover').textContent=money(8000-m);$('growthValue').textContent=g+'%';$('safeAmount').textContent=money(m*w.safe);$('steadyAmount').textContent=money(m*w.steady);$('equityAmount').textContent=money(m*w.equity);$('stepValue').textContent=step+'%';$('stepNote').textContent='Year 2: '+money(m*(1+step/100))+'/month. Year 5: '+money(m*Math.pow(1+step/100,4))+'/month. This assumes your future income can support the increase.';$('projectionGoal').textContent='YOUR PATH TO '+goalName();$('years').textContent=base.reached?duration(base.months):'60+ years';$('age').textContent=base.reached?'Around age '+(19+Math.floor(base.months/12))+'. The timeline changes with your choices.':'This goal is not reached within this 60-year illustration.';$('goalSummary').textContent='Your destination: '+goalName()+'. With the current plan: '+(base.reached?duration(base.months):'more than 60 years')+'.';document.querySelector('.clarity-goal strong').textContent=goalKind==='usd'?'$1,000,000':money(goal);$('fxBox').hidden=goalKind!=='usd';document.querySelectorAll('[data-goal]').forEach(b=>b.setAttribute('aria-pressed',b.dataset.goal===goalKind));document.querySelectorAll('[data-mix]').forEach(b=>b.setAttribute('aria-pressed',+b.dataset.mix===g));
const n=base.months,lo=series(m,r-.03,step,n),hi=series(m,r+.03,step,n),fd=series(m,.06,step,n),sav=series(m,.04,step,n),max=Math.max(...hi,...fd,...sav,...base.points)*1.05;function path(points){return points.map((v,i)=>(i?'L':'M')+(10+i/n*500).toFixed(2)+' '+(190-v/max*175).toFixed(2)).join(' ')}$('line').setAttribute('d',path(base.points));$('fdLine').setAttribute('d',path(fd));$('savingsLine').setAttribute('d',path(sav));const bottom=lo.map((v,i)=>[10+i/n*500,190-v/max*175]).reverse().map(([x,y])=>'L'+x.toFixed(2)+' '+y.toFixed(2)).join(' ');$('band').setAttribute('d',path(hi)+bottom+'Z');$('chartEnd').textContent=duration(n);$('rangeNote').textContent='Sensitivity: '+(high.reached?duration(high.months):'60+ years')+' to '+(low.reached?duration(low.months):'60+ years')+'. This is not a probability range.';const extra=project(m+500,r,step,goal);$('nudge').textContent=m<=7500&&base.reached?'An extra ₹500/month could shorten this scenario by '+(base.months-extra.months)+' months.':m>7500?'You’ve allocated nearly all the current income. Leave room for essentials before increasing it.':'Try a smaller first milestone or a sustainable yearly increase.';$('assumptions').textContent=(r*100).toFixed(2)+'% blended annual return; '+step+'% yearly contribution increase. Fees and taxes excluded. Returns are not guaranteed.';$('inflation').textContent='At illustrative 5% yearly inflation, '+money(goal)+' after '+duration(n)+' would buy about what '+money(goal/Math.pow(1.05,n/12))+' buys today.';const buffer=+$('bufferAmount').value;$('bufferValue').textContent=money(buffer);$('bufferProgress').value=buffer;$('bufferNote').textContent=money(buffer)+' of a ₹15,000 example buffer. '+(buffer>=15000?'Example target reached. Your real need depends on essential expenses.':'Keep emergency money accessible and separate. This example target is not a universal recommendation.');replay();}
const products=[{name:'Savings account',tier:'SAFETY NET',icon:'↙',desc:'For unexpected expenses and money you need soon.',risk:'Lower · ●○○○○',lock:'Usually accessible',returns:'4% model input',fees:'Account charges vary',note:'Inflation can erode buying power; bank and withdrawal conditions matter.'},{name:'Fixed deposit',tier:'STEADY',icon:'≈',desc:'For a known horizon and more predictable interest.',risk:'Lower · ●●○○○',lock:'Chosen term; early-exit terms vary',returns:'6% model input',fees:'Early-exit penalties may apply',note:'Rate and term depend on the deposit. The model omits tax and early-exit costs.'},{name:'Index fund',tier:'GROWTH',icon:'↗',desc:'For long-term goals with room for market declines.',risk:'Higher · ●●●●○',lock:'Exit terms vary by fund',returns:'9% model input',fees:'Expense ratio; exit load may apply',note:'No guaranteed return. A SIP is a contribution method, not another investment.'}];
$('learnCards').innerHTML=products.map((p,i)=>`<article class="option"><div class="card-top"><span class="icon">${p.icon}</span><span class="tag">${p.tier}</span></div><h3>${p.name}</h3><p>${p.desc}</p><dl class="traits"><div><dt>Risk</dt><dd>${p.risk}</dd></div><div><dt>Access</dt><dd>${p.lock}</dd></div><div><dt>Return*</dt><dd>${p.returns}</dd></div><div><dt>Fees</dt><dd>${p.fees}</dd></div></dl><label class="compare-check"><input type="checkbox" data-compare="${i}"> Compare this option</label><details><summary>The honest trade-off <span>+</span></summary><p>${p.note}</p></details></article>`).join('');
$('learnCards').insertAdjacentHTML('afterend','<p class="hint">*Return numbers are editable-model assumptions shown for learning, not typical returns, quotes or promises. Risk dots are a simplified teaching aid, not an official Riskometer.</p>');
document.querySelectorAll('[data-compare]').forEach(input=>input.onchange=()=>{const i=+input.dataset.compare;if(input.checked){if(selected.length===2){input.checked=false;$('compareStatus').textContent='Two is enough to compare clearly. Deselect one before choosing another.';return}selected.push(i)}else selected=selected.filter(n=>n!==i);$('comparison').hidden=selected.length!==2;$('compareStatus').textContent=selected.length+'/2 selected. '+(selected.length===2?'Compare risk, access and cost before deciding.':'Choose '+(2-selected.length)+' more.');if(selected.length===2){const a=products[selected[0]],b=products[selected[1]];$('comparison').innerHTML='<h3>Two options. The trade-offs.</h3><table><thead><tr><th scope="col">Trait</th><th scope="col">'+a.name+'</th><th scope="col">'+b.name+'</th></tr></thead><tbody>'+[['Risk','risk'],['Access','lock'],['Model return','returns'],['Fees','fees']].map(([l,k])=>'<tr><th scope="row">'+l+'</th><td>'+a[k]+'</td><td>'+b[k]+'</td></tr>').join('')+'</tbody></table>'}});
function persist(){try{localStorage.setItem('honest-million-v2',JSON.stringify(saved));return true}catch{return false}}
function journey(){const total=saved?saved.safe+saved.steady+saved.equity:0,goal=saved?.goal||target();$('balance').textContent=money(total);$('safeHolding').textContent=money(saved?.safe||0);$('steadyHolding').textContent=money(saved?.steady||0);$('growthHolding').textContent=money(saved?.equity||0);$('progressBar').style.width=clamp(total/goal*100,0,100)+'%';$('percent').textContent=(total/goal*100).toFixed(1)+'% of the way';$('journeyGoal').textContent=money(goal);$('journeyText').textContent=saved?money(saved.monthly)+'/month initially · '+saved.months+' practice months logged.':'Save your plan to start a practice journey.';$('contribute').disabled=!saved;$('checkin').textContent=saved?.months?'Practice contribution logged. No other task in this simulated month.':'No real transactions. Each click advances one simulated month.';$('milestones').innerHTML=[50000,100000,500000].map(n=>'<span class="'+(total>=n?'complete':'')+'">'+(total>=n?'✓ ':'○ ')+money(n)+'</span>').join('');$('history').hidden=$('calm').checked;$('history').textContent=saved?.logs.length?saved.logs.slice(-6).map(l=>'Month '+l.month+': '+money(l.amount)).join(' · '):'No practice contributions yet.';}
$('save').onclick=()=>{saved={monthly:+$('monthly').value,growth:+$('growth').value,step:+$('stepup').value,goal:target(),goalKind,fx:+$('fx').value,buffer:+$('bufferAmount').value,safe:saved?.safe||0,steady:saved?.steady||0,equity:saved?.equity||0,months:saved?.months||0,logs:saved?.logs||[]};$('saveStatus').textContent=persist()?'Saved on this device. My Money now uses this plan.':'Saved for this session; device storage is unavailable.';journey()};
$('contribute').onclick=()=>{if(!saved)return;const w=mix(saved.growth),m=saved.monthly*Math.pow(1+saved.step/100,Math.floor(saved.months/12));saved.safe+=m*w.safe;saved.steady+=m*w.steady;saved.equity+=m*w.equity;saved.months++;saved.logs.push({month:saved.months,amount:m});persist();journey()};$('calm').onchange=journey;
function replayPaths(g,scenario){const w=mix(g),returns=scenario==='slow'?[-.3,-.1,.02,.03]:[-.3,.18,.12,.08];let a=1e5*w.safe,b=1e5*w.steady,e=1e5*w.equity,c=e,kept=[1e5],sold=[1e5];returns.forEach((r,i)=>{a*=1.03;b*=1.05;e*=1+r;c*=i===0?1+r:1.03;kept.push(a+b+e);sold.push(a+b+c)});return{kept,sold}}
function replay(){const y=+$('replayYear').value,p=replayPaths(+$('growth').value,$('scenario').value);$('replayLabel').textContent=y;$('scenarioTag').textContent=y===0?'BEFORE THE DROP':'HYPOTHETICAL YEAR '+y;$('stormAmount').textContent=money(p.kept[y]);$('kept').textContent=money(p.kept[y]);$('sold').textContent=money(p.sold[y]);const all=[...p.kept,...p.sold],min=Math.min(...all)*.9,max=Math.max(...all)*1.1;$('stormLine').setAttribute('d',p.kept.slice(0,y+1).map((v,i)=>(i?'L':'M')+(i*100)+' '+(110-(v-min)/(max-min)*100)).join(' '));$('stormText').textContent=y<2?'The growth portion loses 30% in year 1. Both paths share that loss before any switch to cash.':'By year '+y+', '+(p.kept[y]>=p.sold[y]?'keeping the mix is ahead':'switching growth to cash is ahead')+' in this particular scenario. A different future can reverse the result.';document.querySelector('.storm-card').classList.toggle('crashed',y===1)}
function stopReplay(){clearInterval(timer);timer=null;$('playReplay').textContent='Play replay ▷'}$('playReplay').onclick=()=>{if(timer){stopReplay();return}if(+$('replayYear').value===4)$('replayYear').value=0;$('playReplay').textContent='Pause replay Ⅱ';replay();timer=setInterval(()=>{$('replayYear').value=+$('replayYear').value+1;replay();if(+$('replayYear').value===4)stopReplay()},1300)};$('replayYear').oninput=()=>{stopReplay();replay()};$('scenario').onchange=()=>{stopReplay();replay()};
document.querySelectorAll('[data-feeling]').forEach(b=>b.onclick=()=>{$('feelingReply').textContent=b.dataset.feeling==='scared'?'That’s a normal response. Check your buffer, time horizon and comfort with losses. A lower-growth mix is an option; no plan is worth risking essential expenses.':'Knowing your limits helps. Revisit your plan when your needs change, and remember that recovery timing is uncertain.'});
document.querySelectorAll('[data-goal]').forEach(b=>b.onclick=()=>{goalKind=b.dataset.goal;update();if(!saved)journey()});document.querySelectorAll('[data-mix]').forEach(b=>b.onclick=()=>{$('growth').value=b.dataset.mix;update()});['monthly','growth','stepup','bufferAmount','fx'].forEach(id=>$(id).addEventListener('input',update));$('reset').onclick=()=>{stopReplay();saved=null;try{localStorage.removeItem('honest-million-v2')}catch{}goalKind='1000000';$('monthly').value=2000;$('growth').value=50;$('stepup').value=0;$('bufferAmount').value=0;$('fx').value=85;$('replayYear').value=0;$('scenario').value='recovery';$('saveStatus').textContent='Practice data reset.';update();journey()};
if(saved){$('monthly').value=saved.monthly;$('growth').value=saved.growth;$('stepup').value=saved.step||0;$('bufferAmount').value=saved.buffer||0;goalKind=['1000000','10000000','usd'].includes(saved.goalKind)?saved.goalKind:'1000000';$('fx').value=saved.fx||85}update();journey();
